        'village.subtitle': `Donde el Arte del Tejido Vive`,
        'village.p1': `Ubicado a 35 km del centro de Hanói, el pueblo de Phú Vinh tiene más de 400 años de historia. De humildes fibras de ratán y tiras de bambú, artesanos hábiles crean obras maestras.`,
