        'mem.val.private': `Privé`,
        'mem.securePay': `Paiement sécurisé`,
        'hero.sug1.t': `Chaise Nid`,
        'hero.sug2.t': `Lustre`,
        'hero.sug3.t': `Sac en Rotin`,
        'hero.sug4.t': `Balançoire`,
        'hero.sug5.t': `Miroir Soleil`,
        'hero.sug6.t': `Table à Thé`,
        'story1.tag': `ARTISAN`,
        'story1.title': `Mains Magiques`,
        'story1.desc': `60 ans d'expérience`,
        'story1.full': `Nguyễn Văn Bảy, né en 1938, a commencé à tisser à l'âge de 8 ans sous la direction de son père. En 60 ans, ses mains ont créé des milliers d'œuvres uniques, dont un ensemble de 12 plateaux dragon-phénix exposés au Musée d'ethnologie du Vietnam. Son tissage décoratif est considéré comme le plus raffiné de Phú Vinh : chaque plateau prend jusqu'à 3 mois avec plus de 40 000 nœuds. En 2018, il obtient le titre d’Artisan Méritoire.`,
        'story1.link': `Voir`,
        'story2.tag': `HISTOIRE`,
        'story2.title': `Tribut`,
        'story2.desc': `18ème siècle...`,
        'story2.full': `Les documents historiques montrent que sous le règne de l'empereur Lê Hiển Tông (XVIIIe siècle), les autorités locales présentaient des boîtes en bambou de Phú Vinh, des plateaux à thé et des assiettes de service à la cour royale. L'empereur en fut ravi et ordonna au village d'approvisionner régulièrement la cour intérieure. Ce fut le premier âge d’or du village artisanal.`,
        'story2.link': `Voir`,
        'story3.tag': `JEUNES`,
        'story3.title': `Amazon`,
        'story3.desc': `Génération Z...`,
        'story3.full': `Nguyễn Minh Quân, né en 1995, a obtenu son diplôme universitaire et est retourné au village au lieu de rester en ville. Il a fondé Phú Vinh Craft Export, vendant sur Amazon et Etsy. En seulement 2 ans, les revenus d'exportation de son équipe ont atteint 3 milliards de VND/an, apportant des produits à des clients dans 28 pays.`,
        'story3.link': `Voir`,
        'story4.tag': `FAMILLE`,
        'story4.title': `Héritage`,
        'story4.desc': `Transmission...`,
        'story4.full': `La famille de Mme Trần Thị Hoa est l'une des cinq générations de familles de tisserands de Phú Vinh. De l’arrière-grand-mère à la fille de 7 ans, chacun maîtrise au moins une étape. Mme Hoa dit : « Personne ne nous enseigne formellement. Les enfants regardent leurs parents et les imitent, et à un moment donné, ils savent comment le faire. »`,
        'story4.link': `Voir`,
        'story5.tag': `HONNEUR`,
        'story5.title': `UNESCO`,
        'story5.desc': `Efforts...`,
        'story5.full': `En 2019, Phú Vinh a été ajouté à la liste de l'UNESCO des villages d'artisanat traditionnel représentatifs de l'Asie du Sud-Est à préserver. Pour y parvenir, le gouvernement du district et l'Association des artisans de Phú Vinh ont passé 4 ans à constituer le dossier, documentant et numérisant plus de 200 techniques de tissage traditionnelles.`,
        'story5.link': `Voir`,
        'story6.tag': `ECOLOGIE`,
        'story6.title': `Conservation`,
        'story6.desc': `Nature...`,
        'story6.full': `Face à la raréfaction des matières premières, un groupe d'artisans de Phú Vinh s'est associé en 2020 à l'Institut d'écologie et des ressources biologiques pour créer la première pépinière de rotin du Vietnam, au pied du village. Le projet « Green Phú Vinh » a planté plus de 15 000 plants de rotin sur 5 hectares.`,
        'story6.link': `Voir`,
        'nav.village': `À propos du village`,
        'nav.stories': `Histoires`,
        'nav.process': `Processus`,
        'nav.vr': `Visite VR 360°`,
