        'hero.title1': `Créez des designs en bambou et en rotin à partir de`,
        'hero.title2': `Votre imagination`,
        'hero.title3': ``,
        'hero.desc': `IA formée sur des milliers de modèles de tissage Phú Vinh : dessinez votre idée en quelques secondes.`,
        'hero.generate': `Générer`,
