        'village.badge': `400 ans de patrimoine`,
        'village.title': `Village artisanal de Phú Vinh`,
        'village.subtitle': `Là où l’art du tissage perdure`,
        'village.p1': `Situé à 35 km du centre de Hanoï, le village de Phú Vinh a plus de 400 ans d'histoire. À partir d’humbles fibres de rotin et de bandes de bambou, des artisans qualifiés créent des œuvres d’art magistrales.`,
        'village.p2': `Le tissage de Phú Vinh est réputé pour ses techniques complexes, avec des centaines de motifs : tissage simple anneau, double anneau, chevrons, ajouré... Chaque pièce porte l'âme de son artisan.`,
        'village.stat1': `Des années d'histoire`,
