        'hero.sug5.t': `Sonnen-Spiegel`,
        'hero.sug6.t': `Tisch`,
        'story1.tag': `HANDWERKER`,
        'story1.title': `Magische Hände`,
        'story1.desc': `60 Jahre Erfahrung`,
        'story1.full': `Nguyễn Văn Bảy, geboren 1938, begann im Alter von 8 Jahren unter der Anleitung seines Vaters mit dem Weben. Im Laufe von 60 Jahren haben seine Hände Tausende einzigartiger Werke geschaffen, darunter ein Set aus 12 Drachen-Phönix-Tabletts, die im Vietnam Museum of Ethnology ausgestellt sind. Seine dekorative Weberei gilt als die feinste in Phú Vinh – jedes Tablett benötigt mit über 40.000 Knoten bis zu drei Monate. Im Jahr 2018 wurde ihm der Titel „Verdienstvoller Handwerker“ verliehen.`,
        'story1.link': `Ansehen`,
        'story2.tag': `GESCHICHTE`,
        'story2.title': `Tribut`,
        'story2.desc': `18. Jahrhundert...`,
        'story2.full': `Historische Aufzeichnungen zeigen, dass während der Herrschaft von Kaiser Lê Hiển Tông (18. Jahrhundert) örtliche Beamte dem königlichen Hof Phú Vinh-Bambusboxen, Teetabletts und Servierteller überreichten. Der Kaiser war erfreut und befahl dem Dorf, den Innenhof regelmäßig zu beliefern. Dies war das erste goldene Zeitalter des Handwerkerdorfes.`,
        'story2.link': `Ansehen`,
        'story3.tag': `JUGEND`,
        'story3.title': `Amazon`,
        'story3.desc': `Generation Z...`,
        'story3.full': `Nguyễn Minh Quân, geboren 1995, schloss sein Studium ab und kehrte ins Dorf zurück, anstatt in der Stadt zu bleiben. Er gründete Phú Vinh Craft Export und verkaufte auf Amazon und Etsy. In nur zwei Jahren erreichte der Exportumsatz seines Teams 3 Milliarden VND/Jahr und brachte Produkte an Kunden in 28 Ländern.`,
        'story3.link': `Ansehen`,
        'story4.tag': `FAMILIE`,
        'story4.title': `Erbe`,
        'story4.desc': `Familie...`,
        'story4.full': `Die Familie von Frau Trần Thị Hoa ist eine von fünf Generationen Weberfamilien in Phú Vinh. Von der Urgroßmutter bis zur 7-jährigen Tochter beherrscht jeder mindestens einen Schritt. Frau Hoa sagt: „Niemand unterrichtet uns offiziell. Kinder beobachten ihre Eltern und ahmen nach, und irgendwann wissen sie einfach, wie es geht.“`,
        'story4.link': `Ansehen`,
        'story5.tag': `EHRE`,
        'story5.title': `UNESCO`,
        'story5.desc': `Bemühungen...`,
        'story5.full': `Im Jahr 2019 wurde Phú Vinh in die UNESCO-Liste der repräsentativen traditionellen Handwerksdörfer Südostasiens aufgenommen, die erhalten werden müssen. Um dies zu erreichen, haben die Bezirksregierung und der Phú Vinh Artisans Association vier Jahre lang das Dossier erstellt und über 200 traditionelle Webtechniken dokumentiert und digitalisiert.`,
        'story5.link': `Ansehen`,
        'story6.tag': `ÖKOLOGIE`,
        'story6.title': `Naturschutz`,
        'story6.desc': `Natur...`,
        'story6.full': `Angesichts immer knapper werdender Rohstoffe schloss sich 2020 eine Gruppe von Kunsthandwerkern aus Phú Vinh mit dem Institut für Ökologie und biologische Ressourcen zusammen, um am Fuße des Dorfes Vietnams erste Rattan-Gärtnerei zu errichten. Das Projekt „Green Phú Vinh“ hat auf 5 Hektar über 15.000 Rattanpflanzen gepflanzt.`,
        'story6.link': `Ansehen`,
        'nav.village': `Über Village`,
