        'hero.suggestions': `Beliebte Vorschläge`,
        'village.badge': `400 Jahre Erbe`,
        'village.title': `Handwerkerdorf Phú Vinh`,
        'village.subtitle': `Wo die Kunst des Webens weiterlebt`,
        'village.p1': `Das Dorf Phú Vinh liegt 35 km vom Zentrum von Hanoi entfernt und blickt auf eine über 400-jährige Geschichte zurück. Aus einfachen Rattanfasern und Bambusstreifen erschaffen erfahrene Kunsthandwerker meisterhafte Kunstwerke.`,
        'village.p2': `Die Weberei von Phú Vinh ist bekannt für ihre komplizierten Techniken mit Hunderten von Mustern: Einzelringbindung, Doppelringbindung, Fischgrätenmuster, Lochmuster ... Jedes Stück trägt die Seele seines Herstellers in sich.`,
