        'hero.sug1.t': `Sedia Nido`,
        'hero.sug2.t': `Lampadario`,
        'hero.sug3.t': `Borsa in rattan`,
        'hero.sug4.t': `Altalena`,
        'hero.sug5.t': `Specchio Sole`,
        'hero.sug6.t': `Tavolo`,
        'story1.tag': `ARTIGIANO`,
        'story1.title': `Mani Magiche`,
        'story1.desc': `60 anni di esperienza`,
        'story1.full': `Nguyễn Văn Bảy, nato nel 1938, ha iniziato a tessere all'età di 8 anni sotto la guida di suo padre. In 60 anni, le sue mani hanno creato migliaia di opere uniche, tra cui una serie di 12 vassoi drago-fenice esposti al Museo Etnologico del Vietnam. La sua tessitura decorativa è considerata la più raffinata di Phú Vinh: ogni vassoio richiede fino a 3 mesi con oltre 40.000 nodi. Nel 2018 gli è stato conferito il titolo di Artigiano Benemerito.`,
        'story1.link': `Vedi`,
        'story2.tag': `STORIA`,
        'story2.title': `Tributo`,
        'story2.desc': `18° secolo...`,
        'story2.full': `I documenti storici mostrano che durante il regno dell'imperatore Lê Hiển Tông (XVIII secolo), i funzionari locali presentarono alla corte reale scatole di bambù Phú Vinh, vassoi da tè e piatti da portata. L'imperatore ne fu felice e ordinò al villaggio di rifornire regolarmente la corte interna. Questa fu la prima età dell'oro del villaggio artigianale.`,
        'story2.link': `Vedi`,
        'story3.tag': `GIOVANI`,
        'story3.title': `Amazon`,
        'story3.desc': `Generazione Z...`,
        'story3.full': `Nguyễn Minh Quân, nato nel 1995, si è laureato all'università ed è tornato al villaggio invece di restare in città. Ha fondato Phú Vinh Craft Export, vendendo su Amazon ed Etsy. In soli 2 anni, il fatturato derivante dalle esportazioni del suo team ha raggiunto i 3 miliardi di VND/anno, portando prodotti a clienti in 28 paesi.`,
        'story3.link': `Vedi`,
        'story4.tag': `FAMIGLIA`,
        'story4.title': `Eredità`,
        'story4.desc': `Famiglia...`,
        'story4.full': `La famiglia della signora Trần Thị Hoa è una delle famiglie di tessitori di cinque generazioni a Phú Vinh. Dalla bisnonna alla figlia di 7 anni, tutti padroneggiano almeno un passo. La signora Hoa dice: "Nessuno ce lo insegna formalmente. I bambini guardano i loro genitori e imitano, e ad un certo punto sanno semplicemente come farlo".`,
        'story4.link': `Vedi`,
        'story5.tag': `ONORE`,
        'story5.title': `UNESCO`,
        'story5.desc': `Sforzi...`,
        'story5.full': `Nel 2019, Phú Vinh è stato aggiunto all'elenco dell'UNESCO dei villaggi artigianali tradizionali rappresentativi del sud-est asiatico che necessitano di conservazione. Per raggiungere questo obiettivo, il governo del distretto e l’Associazione degli Artigiani di Phú Vinh hanno impiegato 4 anni per costruire il dossier, documentando e digitalizzando oltre 200 tecniche di tessitura tradizionali.`,
        'story5.link': `Vedi`,
        'story6.tag': `ECOLOGIA`,
        'story6.title': `Conservazione`,
        'story6.desc': `Natura...`,
        'story6.full': `Di fronte a materie prime sempre più scarse, nel 2020 un gruppo di artigiani di Phú Vinh ha collaborato con l'Istituto di ecologia e risorse biologiche per creare il primo vivaio in rattan del Vietnam, ai piedi del villaggio. Il progetto "Green Phú Vinh" ha piantato oltre 15.000 piante di rattan su 5 ettari.`,
        'story6.link': `Vedi`,
        'nav.village': `A proposito del villaggio`,
