        'hero.title1': `Crea disegni in bambù e rattan da`,
        'hero.title2': `La tua immaginazione`,
        'hero.title3': ``,
        'hero.desc': `L'intelligenza artificiale è stata addestrata su migliaia di modelli di tessitura Phú Vinh: disegna la tua idea in pochi secondi.`,
        'hero.generate': `Generare`,
        'hero.generating': `Creazione...`,
