        'hero.suggestions': `Suggerimenti popolari`,
        'village.badge': `400 anni di tradizione`,
        'village.title': `Villaggio artigianale di Phú Vinh`,
        'village.subtitle': `Dove continua a vivere l'arte della tessitura`,
        'village.p1': `Situato a 35 km dal centro di Hanoi, il villaggio di Phú Vinh ha oltre 400 anni di storia. Dalle umili fibre di rattan e dalle strisce di bambù, abili artigiani creano opere d'arte magistrali.`,
        'village.p2': `La tessitura Phú Vinh è rinomata per le sue tecniche intricate, con centinaia di motivi: trama ad anello singolo, doppio anello, spina di pesce, traforata... Ogni pezzo porta con sé l'anima del suo creatore.`,
