        'hero.sug6.t': `Bord`,
        'story1.tag': `HÅNDVERKER`,
        'story1.title': `Magiske Hender`,
        'story1.desc': `60 års erfaring`,
        'story1.full': `Nguyễn Văn Bảy, født i 1938, begynte å veve i en alder av 8 under sin fars veiledning. I løpet av 60 år har hendene hans skapt tusenvis av unike verk, inkludert et sett med 12 drage-føniks-brett vist på Vietnam Museum of Ethnology. Hans dekorative veving regnes som den fineste i Phú Vinh - hvert brett tar opptil 3 måneder med over 40 000 knop. I 2018 ble han tildelt tittelen Meritorious Artisan.`,
        'story1.link': `Se`,
        'story2.tag': `HISTORIE`,
        'story2.title': `Tributt`,
        'story2.desc': `18. århundre...`,
        'story2.full': `Historiske poster viser at under keiser Lê Hiển Tôngs regjeringstid (1700-tallet) presenterte lokale embetsmenn Phú Vinh bambusbokser, tebrett og serveringsfat til det kongelige hoffet. Keiseren var henrykt og beordret landsbyen å forsyne det indre hoffet regelmessig. Dette var den første gullalderen til håndverkslandsbyen.`,
        'story2.link': `Se`,
        'story3.tag': `UNGDOM`,
        'story3.title': `Amazon`,
        'story3.desc': `Generasjon Z...`,
        'story3.full': `Nguyễn Minh Quân, født 1995, ble uteksaminert fra universitetet og returnerte til landsbyen i stedet for å bli i byen. Han grunnla Phú Vinh Craft Export, og solgte på Amazon og Etsy. På bare 2 år nådde teamets eksportinntekter 3 milliarder VND/år, og brakte produkter til kunder i 28 land.`,
        'story3.link': `Se`,
        'story4.tag': `FAMILIE`,
        'story4.title': `Arv`,
        'story4.desc': `Familie...`,
        'story4.full': `Familien til fru Trần Thị Hoa er en av fem-generasjons vevefamilier i Phú Vinh. Fra oldemor til den 7 år gamle datteren, alle mestrer minst ett trinn. Fru Hoa sier: "Ingen lærer oss formelt. Barn ser på foreldrene sine og imiterer, og på et tidspunkt vet de bare hvordan de skal gjøre det."`,
        'story4.link': `Se`,
        'story5.tag': `ÆRE`,
        'story5.title': `UNESCO`,
        'story5.desc': `Innsats...`,
        'story5.full': `I 2019 ble Phú Vinh lagt til UNESCOs liste over representative tradisjonelle håndverkslandsbyer i Sørøst-Asia som trenger bevaring. For å oppnå dette brukte distriktsregjeringen og Phú Vinh Artisans Association 4 år på å bygge dokumentasjonen, dokumentere og digitalisere over 200 tradisjonelle veveteknikker.`,
        'story5.link': `Se`,
        'story6.tag': `ØKOLOGI`,
        'story6.title': `Bevaring`,
        'story6.desc': `Natur...`,
        'story6.full': `Stilt overfor stadig knappere råvarer, gikk en gruppe Phú Vinh-håndverkere i 2020 sammen med Institute of Ecology and Biological Resources for å etablere Vietnams første rottingbarnehage ved foten av landsbyen. Prosjektet "Green Phú Vinh" har plantet over 15 000 rottingplanter på 5 hektar.`,
        'story6.link': `Se`,
