        'village.p1': `Landsbyen Phú Vinh ligger 35 km fra sentrale Hanoi, og har over 400 års historie. Fra ydmyke rottingfibre og bambusstrimler lager dyktige håndverkere mesterlige kunstverk.`,
        'village.p2': `Phú Vinh-veving er kjent for sine intrikate teknikker, med hundrevis av mønstre: enkelt-ring-veving, dobbel-ring, sildebein, openwork... Hvert stykke bærer sjelen til sin skaper.`,
